import type { AsamUploadHandler } from '@asam-ui/ui';
export const localUpload: AsamUploadHandler = async ({ file }, context) => {
	context.reportProgress({ loaded: 0, total: file.size });
	await new Promise<void>((resolve, reject) => {
		const timer = setTimeout(resolve, 250);
		context.signal.addEventListener(
			'abort',
			() => {
				clearTimeout(timer);
				reject(new Error('cancelled'));
			},
			{ once: true }
		);
	});
	if (context.signal.aborted) throw new Error('cancelled');
	context.reportProgress({ loaded: file.size, total: file.size });
	return {
		id: file.name + ':' + file.size,
		name: file.name,
		url: '/local-demo/' + encodeURIComponent(file.name),
		mimeType: file.type || 'application/octet-stream',
		size: file.size
	};
};

