import { reactive } from 'vue';
import { createYudaoProvider } from '@asam-ui/ui-yudao';
/** Host cache and transport are local to this complete example; no URL is contacted. */
export function createBridge(supportsRefresh = true) {
	const state = reactive({
		supportsRefresh,
		generation: 0,
		slow: false,
		failure: false,
		aborts: 0,
		reads: 0,
		calls: []
	});
	let release = () => undefined;
	const record = (kind, context) =>
		state.calls.push({
			kind,
			scope: context.scope,
			epoch: context.epoch,
			requestId: context.requestId
		});
	const provider = createYudaoProvider({
		dict: {
			async ensure(context) {
				record('ensure', context);
				context.signal.throwIfAborted();
				if (state.slow)
					await new Promise((resolve, reject) => {
						const abort = () => {
							state.aborts++;
							context.signal.removeEventListener('abort', abort);
							reject(context.signal.reason);
						};
						context.signal.addEventListener('abort', abort, { once: true });
						release = () => {
							context.signal.removeEventListener('abort', abort);
							resolve();
						};
					});
				context.signal.throwIfAborted();
				if (state.failure) throw new Error('Local host dictionary failed');
			},
			get(type) {
				if (type !== 'members') throw new Error('Unknown local dictionary');
				state.reads++;
				return [
					{ label: '第一成员 G' + state.generation, value: 1 },
					{ label: '第二成员 G' + state.generation, value: 2 }
				];
			},
			...(supportsRefresh
				? {
						async refresh(context) {
							record('refresh', context);
							context.signal.throwIfAborted();
							state.generation++;
						}
					}
				: {})
		}
	});
	return { state, provider, release: () => release() };
}

import { createYudaoProvider } from '@asam-ui/ui-yudao';
import {
	createAsamDataRuntime,
	defineAsamOptions,
	resolveAsamOptions,
	resolveAsamPage
} from '@asam-ui/ui';
/** All transports and files are local fixtures; this function contacts no endpoint. */
export async function runYudaoBridgeContract() {
	const observations = [];
	const check = (value, label) => {
		if (!value) throw Error(label);
	};
	const record = (phase, state) => observations.push({ phase, state });
	const requests = [];
	const notices = [];
	const ownedCause = Error('host already notified');
	const bridge = {
		request: async (config, context) => {
			requests.push({ config, context });
			return { code: 0, data: [{ label: 'Local', value: 0 }] };
		},
		upload: async (config, input, context) => {
			context.reportProgress({ loaded: input.file.size, total: input.file.size });
			return { config, input, context };
		},
		isErrorNotified: (cause) => cause === ownedCause,
		onError: (error) => {
			notices.push(error);
		}
	};
	const provider = createYudaoProvider(bridge);
	check(requests.length === 0 && notices.length === 0, 'construction must be inert');
	check(
		provider.request === bridge.request &&
			provider.upload === bridge.upload &&
			provider.onError === bridge.onError &&
			provider.isErrorNotified === bridge.isErrorNotified,
		'callbacks must retain identity'
	);
	check(
		Object.isFrozen(provider) &&
			Object.isFrozen(provider.pagination) &&
			!Object.isFrozen(bridge),
		'freeze provider rather than host bridge'
	);
	record('yudao-inert-construction-frozen-provider-and-original-callbacks', {
		calls: requests.length,
		notices: notices.length,
		callbackIdentity: true,
		providerFrozen: true,
		paginationFrozen: true,
		hostFrozen: false,
		pagination: provider.pagination
	});
	const runtime = createAsamDataRuntime({ provider, scope: 'yudao-contract' });
	const context = runtime.createContext();
	try {
		const params = { tenant: 'local' },
			data = { body: true };
		const source = defineAsamOptions().request({
			request: { url: '/local-contract', method: 'post', params, data }
		});
		const options = await resolveAsamOptions(source, { provider, context });
		check(requests.length === 1 && requests[0].context === context, 'request context identity');
		check(
			requests[0].config.params === params && requests[0].config.data === data,
			'request payload ownership'
		);
		check(options[0].value === 0, 'request unwrap and core normalization');
		record('yudao-real-core-request-context-and-payload-ownership', {
			url: requests[0].config.url,
			method: requests[0].config.method,
			scope: context.scope,
			sameContext: true,
			sameParams: true,
			sameData: true,
			values: options.map((o) => o.value)
		});
		const progress = [],
			input = {
				file: new File(['abc'], 'local.txt', { type: 'text/plain' }),
				fieldName: 'attachment',
				data: { tenant: 'local', payload: new Blob(['z']) }
			};
		const uploadContext = {
			...context,
			reportProgress: (p) => {
				progress.push(p.loaded);
			}
		};
		const config = { url: '/local-upload', method: 'put', params };
		const uploaded = await provider.upload(config, input, uploadContext);
		if (typeof uploaded !== 'object' || uploaded === null) throw Error('upload echo');
		check(
			Reflect.get(uploaded, 'input') === input &&
				Reflect.get(uploaded, 'context') === uploadContext &&
				Reflect.get(uploaded, 'config') === config,
			'upload passthrough identity'
		);
		check(progress.length === 1 && progress[0] === 3, 'upload progress forwarding');
		record('yudao-upload-original-transport-and-progress-passthrough', {
			sameConfig: true,
			sameInput: true,
			sameContext: true,
			name: input.file.name,
			fieldName: input.fieldName,
			progress
		});
		const row = { label: 'Decoded', value: false };
		const values = [];
		for (const response of [
			[row],
			{ data: [row] },
			{ code: 0, data: [row] },
			{ code: 200, data: [row] }
		]) {
			const source = defineAsamOptions().api({
				api: async () => response,
				params: undefined
			});
			values.push((await resolveAsamOptions(source, { provider, context }))[0].value);
		}
		const badCodes = ['0', 500, null, undefined];
		const failures = [];
		for (const response of [
			...badCodes.map((code) => ({ code, data: [row] })),
			{ code: 0, data: { data: [row] } }
		]) {
			try {
				await resolveAsamOptions(
					defineAsamOptions().api({ api: async () => response, params: undefined }),
					{ provider, context }
				);
				throw Error('invalid response accepted');
			} catch (error) {
				check(
					typeof error === 'object' &&
						error !== null &&
						Reflect.get(error, 'kind') === 'response',
					'one-envelope response rejection'
				);
				failures.push('response');
			}
		}
		check(
			values.length === 4 && values.every((value) => value === false),
			'accepted envelopes preserve false'
		);
		record('yudao-one-layer-options-and-five-response-rejections', { values, failures });
		const pages = [
			{ list: [{ id: 0 }], total: 1 },
			{ code: 0, data: { list: [{ id: 0 }], total: 1 } },
			{ code: 200, list: [{ id: 0 }], total: 1 }
		].map((response) => resolveAsamPage(response, undefined, provider));
		for (const page of pages) check(page.total === 1 && page.list[0].id === 0, 'page decoding');
		let ambiguous = false;
		try {
			resolveAsamPage(
				{ code: 0, list: [{ id: 1 }], total: 1, data: { list: [{ id: 2 }], total: 1 } },
				undefined,
				provider
			);
		} catch (error) {
			ambiguous =
				typeof error === 'object' &&
				error !== null &&
				Reflect.get(error, 'kind') === 'response';
		}
		check(ambiguous, 'competing page paths rejected');
		record('yudao-page-default-keys-one-envelope-and-ambiguity', {
			pages: pages.map((page) => ({
				ids: page.list.map((row) => row.id),
				total: page.total
			})),
			ambiguous
		});
		const owned = { kind: 'request', message: 'owned', cause: ownedCause, notified: false };
		const ownedResult = runtime.reportError(owned, context);
		check(
			ownedResult.notified && notices.length === 0,
			'host ownership suppresses duplicate notice'
		);
		const fresh = { kind: 'request', message: 'new', cause: Error('new'), notified: false };
		const first = runtime.reportError(fresh, context),
			second = runtime.reportError(fresh, context);
		check(
			first === second && notices.length === 1 && first.notified,
			'normal notice deduplicates'
		);
		record('yudao-explicit-host-error-ownership-and-notice-deduplication', {
			hostOwnedNotified: ownedResult.notified,
			freshNotified: first.notified,
			notices: notices.length,
			sameReportedError: first === second
		});
		const invalid = [
			null,
			[],
			'bridge',
			{ request: 1 },
			{ upload: 1 },
			{ isErrorNotified: true },
			{ onError: true },
			{ dict: null },
			{ dict: [] },
			{ dict: {} },
			{ dict: { ensure: async () => {}, get: 1 } },
			{ dict: { ensure: 1, get: () => [] } },
			{ dict: { ensure: async () => {}, get: () => [], refresh: 1 } }
		];
		const rejected = [];
		for (const value of invalid) {
			try {
				Reflect.apply(createYudaoProvider, undefined, [value]);
				throw Error('invalid bridge accepted');
			} catch (error) {
				check(
					typeof error === 'object' &&
						error !== null &&
						Reflect.get(error, 'kind') === 'config',
					'bridge shape rejected before IO'
				);
				rejected.push('config');
			}
		}
		const empty = createYudaoProvider({});
		check(
			empty.request === undefined &&
				empty.upload === undefined &&
				empty.dict === undefined &&
				typeof empty.adaptOptions === 'function' &&
				typeof empty.adaptPage === 'function',
			'empty bridge supports decoding only'
		);
		record('yudao-thirteen-invalid-bridges-and-empty-bridge', {
			rejected,
			emptyHasTransport: false,
			emptyHasAdapters: true
		});
		return { status: 'PASS', observations };
	} finally {
		runtime.release(context);
	}
}

import { reactive } from 'vue';
export function createUploadDemo() {
	const state = reactive({
		responseCase: 'valid',
		method: 'default',
		calls: [],
		notices: 0,
		held: 0,
		released: 0,
		abortedHeld: 0,
		transformSameInput: []
	});
	const params = Object.freeze({ tenant: 'local' });
	const data = Object.freeze({ tenant: 'local', payload: new Blob(['extra']) });
	const pending = new Set();
	let transportedInput;
	async function transfer(owner, input, context, method, sameParams) {
		state.calls.push({
			owner,
			name: input.file.name,
			size: input.file.size,
			fieldName: input.fieldName,
			tenant: input.data?.tenant,
			blobText: input.data?.payload instanceof Blob ? await input.data.payload.text() : '',
			fileIsFile: input.file instanceof File,
			scope: context.scope,
			signalIsAbortSignal: context.signal instanceof AbortSignal,
			method,
			sameParams
		});
		context.reportProgress({ loaded: 0 });
		context.reportProgress({ loaded: 2, total: 4 });
		context.reportProgress({ loaded: -1, total: 4 });
		context.reportProgress({ loaded: 5, total: 4 });
		context.reportProgress({ loaded: NaN });
		if (state.responseCase === 'reject') throw Error('local upload transport rejected');
		if (state.responseCase === 'hold') {
			await new Promise((resolve) => {
				const operation = { input, context, resolve };
				pending.add(operation);
				state.held = pending.size;
				context.signal.addEventListener(
					'abort',
					() => {
						if (pending.has(operation)) state.abortedHeld++;
					},
					{ once: true }
				);
			});
		}
		context.reportProgress({ loaded: 4, total: 4 });
	}
	function resource(input, owner) {
		return {
			id: state.responseCase === 'empty-id' ? '' : `${owner}:${input.file.name}`,
			name: input.file.name,
			url:
				state.responseCase === 'unsafe-url'
					? 'javascript:bad'
					: '/local-resources/' + encodeURIComponent(input.file.name),
			mimeType: input.file.type,
			size: state.responseCase === 'nan-size' ? NaN : input.file.size
		};
	}
	const provider = {
		upload: async (config, input, context) => {
			transportedInput = input;
			await transfer(
				'request',
				input,
				context,
				config.method ?? null,
				config.params === params
			);
			return { kind: 'local-resource', name: input.file.name };
		},
		onError: () => {
			state.notices++;
		}
	};
	return {
		state,
		provider,
		params,
		data,
		async upload(input, context) {
			await transfer('handler', input, context, null, true);
			return resource(input, 'handler');
		},
		transform(response, input) {
			state.transformSameInput.push(input === transportedInput);
			if (
				!response ||
				typeof response !== 'object' ||
				Reflect.get(response, 'kind') !== 'local-resource' ||
				Reflect.get(response, 'name') !== input.file.name
			)
				throw Error('invalid local response');
			if (state.responseCase === 'transform-throw') throw Error('local transform rejected');
			const result = resource(input, 'request');
			if (state.responseCase === 'thenable') {
				const thenable = {
					...result,
					then(resolve) {
						resolve(result);
					}
				};
				return thenable;
			}
			return result;
		},
		releaseHeld() {
			for (const operation of pending) {
				pending.delete(operation);
				operation.resolve();
				state.released++;
			}
			state.held = pending.size;
		}
	};
}

